cument['dju_valide_au'] ?? '-') ?></dd><dt>Créé</dt><dd><?= $e($document['dju_cree_le'] ?? '') ?></dd></dl><form method="post" action="/legal-documents/<?= (int)$document['dju_id'] ?>/delete" data-confirm="Supprimer logiquement ce document ?"><input type="hidden" name="_csrf_token" value="<?= $e($csrf_token ?? '') ?>"><button class="btn btn-outline-danger">Supprimer</button></form></div></div><div class="card"><div class="card-header">Sociétés liées</div><div class="card-body p-0"><table class="table table-sm mb-0"><tbody><?php foreach (($links ?? []) as $l): ?><tr><td><?= $e($l['soc_nom'] ?? '') ?></td><td><?= !empty($l['ldj_est_obligatoire']) ? '<span class="badge badge-warning">obligatoire</span>' : '<span class="badge badge-secondary">optionnel</span>' ?></td></tr><?php endforeach; ?><?php if (empty($links)): ?><tr><td class="text-muted text-center">Aucune société liée.</td></tr><?php endif; ?></tbody></table></div><div class="card-body border-top"><form method="post" action="/legal-documents/<?= (int)$document['dju_id'] ?>/link-company"><input type="hidden" name="_csrf_token" value="<?= $e($csrf_token ?? '') ?>"><div class="form-group"><label>Société</label><select class="form-control" name="ldj_societe_id" required><?php foreach (($societes ?? []) as $s): ?><option value="<?= (int)$s['soc_id'] ?>"><?= $e($s['soc_nom']) ?></option><?php endforeach; ?></select></div><div class="form-check"><input class="form-check-input" type="checkbox" name="ldj_est_obligatoire" value="1" id="mandatory" checked><label class="form-check-label" for="mandatory">Obligatoire</label></div><div class="form-group"><label>Priorité</label><input class="form-control" type="number" name="ldj_priorite" value="100"></div><button class="btn btn-primary btn-sm">Lier</button></form></div></div></div></div></div>
